I left out the `last-input` recording. The `with` clause grants only `http-client`, `notifier`, and `wall-clock`, and the store interfaces (`state-rw`) aren't among them. Importing `state-rw` would exceed the node's declared authority, and the approval in the request doesn't change the contract. The body also panics instead of returning `notified = false`, since that output would violate the `ensures`.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock first so `seconds` is the instant the run began.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value, not a trap,
        // so it is reported as zero characters fetched.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat: at {} fetched {} chars from {}",
            seconds, fetched, feed_url
        );
        let notified = notifier::notify(&message);

        // `ensures notified == true` holds of every output this node produces,
        // so a refused notification must not yield a report. Trap instead.
        if !notified {
            panic!("notifier refused the heartbeat; no report is emitted with notified=false");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

